actions.script:
const L = (text) => ec.l10n.localize(text)
const out = ec.service.sync().name('org.moqui.ui.NotificationServices.find#PushHealth').requireNewTransaction(true).call() || {}
allowed = !ec.message.hasError()
ec.message.clearErrors()
const when = (millis) => (millis ? ec.l10n.format(new Date(Number(millis)), 'MMM d, h:mm a') : L('Never'))
const totals = out.totals || {}
totalsText = ec.resource.expand('${deviceCount} devices · ${waitingCount} pushes waiting · ${failedDayCount} failed in the last day · ${missedCount} with missed acknowledgements', '',
    {deviceCount: totals.deviceCount || 0, waitingCount: totals.waitingCount || 0, failedDayCount: totals.failedDayCount || 0, missedCount: totals.missedCount || 0})
deviceList = Array.from(out.deviceList || []).map((d) => Object.assign({}, d, {
    deviceText: [d.providerText, d.platform, d.appId || d.userAgent].filter((part) => part).join(' · '),
    stateText: d.disabledDate ? L('Disabled') : d.missedAcks ? ec.resource.expand('${count} not acknowledged', '', {count: d.unackedCount})
        : d.acknowledges ? L('Working') : L('Sending (no acknowledgements)'),
    stateColor: d.disabledDate ? 'grey' : d.missedAcks ? 'negative' : 'positive',
    registeredText: when(d.lastRegisteredDate),
    pushText: when(d.lastPushDate),
    ackText: when(d.lastAckDate),
    countText: ec.resource.expand('${sent} sent, ${acked} acknowledged, ${failed} failed, ${waiting} waiting', '',
        {sent: d.sentCount, acked: d.ackedCount, failed: d.failedCount, waiting: d.waitingCount}),
    keyText: d.keyed ? '' : L('No push key: its pushes carry no text'),
}))
